  });

  it('renders empty state', () => {
    const { lastFrame } = render(
      <FileTree
        entries={[]}
        selectedIndex={0}
        focused={false}
        loading={false}
        error={null}
        openedPath={null}
      />
    );
    expect(lastFrame()).toContain('No run selected');
  });

  it('renders a single file entry (not selected, not open)', () => {
