    const { lastFrame } = render(
      <FileTree
        entries={[entry]}
        selectedIndex={0}
        focused={false}
        loading={false}
        error={null}
        openedPath={null}
      />
    );
    expect(lastFrame()).toContain('foo.txt');
    expect(lastFrame()).toContain('456B');
  });

  it('renders a selected file entry (focused)', () => {
