  it('handles fullWidth prop', () => {
    const entry = { ...baseEntry, key: 'fw', filePath: '/fw', label: 'fw.txt', isDir: false };
    const { lastFrame } = render(
      <FileTree
        entries={[entry]}
        selectedIndex={0}
        focused={true}
        loading={false}
        error={null}
        openedPath={null}
        fullWidth={true}
      />
    );
    expect(lastFrame()).toContain('fw.txt');
  });

  it('clamps scrollOffset and shows correct visible entries', () => {
    const entries = Array.from({ length: 10 }, (_, i) => ({
      ...baseEntry,
      key: `k${i}`,
      filePath: `/f${i}`,
      label: `file${i}.txt`,
      isDir: false,
      sizeBytes: 100 + i,
      depth: 0,
    }));
    // height = 6, so viewportRows = 3
    const { lastFrame } = render(
      <FileTree
        entries={entries}
        selectedIndex={8}
        focused={true}
        loading={false}
        error={null}
        openedPath={null}
        height={6}
      />
