	it('handles assistant and result messages with different session IDs', async () => {
		const messages = [
			makeAssistantMsg([{ type: 'text', text: 'foo' }], 'sessA'),
			makeResultMsg('success', 'sessB', {
				total_cost_usd: 0.5,
				num_turns: 1,
				duration_ms: 100,
			}),
