import type {
  ReverseGeocoder,
  GeoAddress,
} from '../../../src/domain/ports/ReverseGeocoder';

describe('ReverseGeocoder interface', () => {
  const validGeoAddress: GeoAddress = {
    street: 'Main St',
    streetNumber: '123',
    complement: null,
    neighborhood: 'Downtown',
    city: 'Metropolis',
    metropolitanRegion: null,
    state: 'StateName',
    stateCode: 'ST',
    postalCode: '12345-678',
    country: 'Countryland',
  };

  class MockReverseGeocoder implements ReverseGeocoder {
    async reverseGeocode(latitude: number, longitude: number): Promise<GeoAddress> {
      if (typeof latitude !== 'number' || typeof longitude !== 'number') {
        throw new Error('Invalid coordinates');
      }
      if (latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) {
        throw new Error('Coordinates out of bounds');
      }
      if (latitude === 0 && longitude === 0) {
        return {
          street: null,
          streetNumber: null,
          complement: null,
          neighborhood: null,
          city: null,
          metropolitanRegion: null,
          state: null,
          stateCode: null,
          postalCode: null,
          country: 'Null Island',
        };
      }
      return validGeoAddress;
    }
  }

  it('should resolve a valid coordinate pair to a GeoAddress', async () => {
    const geocoder = new MockReverseGeocoder();
    const result = await geocoder.reverseGeocode(40.7128, -74.0060);
    expect(result).toEqual(validGeoAddress);
  });

  it('should handle coordinates at the edge of valid ranges', async () => {
    const geocoder = new MockReverseGeocoder();
    await expect(geocoder.reverseGeocode(90, 180)).resolves.toEqual(validGeoAddress);
    await expect(geocoder.reverseGeocode(-90, -180)).resolves.toEqual(validGeoAddress);
  });

  it('should return a minimal GeoAddress for (0,0) coordinates', async () => {
    const geocoder = new MockReverseGeocoder();
    const result = await geocoder.reverseGeocode(0, 0);
    expect(result).toEqual({
      street: null,
      streetNumber: null,
      complement: null,
      neighborhood: null,
      city: null,
      metropolitanRegion: null,
      state: null,
      stateCode: null,
      postalCode: null,
      country: 'Null Island',
    });
  });

  it('should throw for coordinates out of bounds', async () => {
    const geocoder = new MockReverseGeocoder();
    await expect(geocoder.reverseGeocode(91, 0)).rejects.toThrow('Coordinates out of bounds');
    await expect(geocoder.reverseGeocode(0, 181)).rejects.toThrow('Coordinates out of bounds');
    await expect(geocoder.reverseGeocode(-91, 0)).rejects.toThrow('Coordinates out of bounds');
    await expect(geocoder.reverseGeocode(0, -181)).rejects.toThrow('Coordinates out of bounds');
  });

  it('should throw for non-numeric coordinates', async () => {
    const geocoder = new MockReverseGeocoder();
    // @ts-expect-error
    await expect(geocoder.reverseGeocode('foo', 0)).rejects.toThrow('Invalid coordinates');
    // @ts-expect-error
    await expect(geocoder.reverseGeocode(0, 'bar')).rejects.toThrow('Invalid coordinates');
  });

  it('should propagate network or provider errors', async () => {
    class ErrorGeocoder implements ReverseGeocoder {
      async reverseGeocode(): Promise<GeoAddress> {
        throw new Error('Network unreachable');
      }
    }
    const geocoder = new ErrorGeocoder();
    await expect(geocoder.reverseGeocode(10, 10)).rejects.toThrow('Network unreachable');
  });

  it('should not allow implementations returning invalid GeoAddress', () => {
    // @ts-expect-error missing required country property
    const invalidGeoAddress: GeoAddress = {
      street: 'Main St',
      streetNumber: '123',
      complement: null,
      neighborhood: null,
      city: null,
      metropolitanRegion: null,
      state: null,
      stateCode: null,
      postalCode: null,
    };
    // @ts-expect-error Implementation returning invalid GeoAddress should be a type error
    class InvalidGeocoder implements ReverseGeocoder {
      async reverseGeocode(): Promise<GeoAddress> {
        // @ts-expect-error
        return invalidGeoAddress;
      }
    }
  });
});
