import { nextTick } from 'vue';
import { useAddressDisplayer } from '../../src/composables/useAddressDisplayer';
import { onUnmounted } from 'vue';

jest.mock('../../src/data/AddressCache.js', () => {
  let currentAddress: any = null;
  let observer: any = null;
  return {
    __esModule: true,
    default: {
      getInstance: () => ({
        get currentAddress() {
          return currentAddress;
        },
        setCurrentAddress(addr: any) {
          currentAddress = addr;
          if (observer && observer.update) observer.update();
        },
        subscribe: (obs: any) => {
          observer = obs;
        },
        unsubscribe: (obs: any) => {
          if (observer === obs) observer = null;
        },
      }),
    },
  };
});

const AddressCache = require('../../src/data/AddressCache.js').default;

describe('useAddressDisplayer', () => {
  let cleanupFns: (() => void)[] = [];

  beforeEach(() => {
    // Reset AddressCache mock state
    AddressCache.getInstance().setCurrentAddress(null);
    cleanupFns = [];
    jest.spyOn(require('vue'), 'onUnmounted').mockImplementation((fn: () => void) => {
      cleanupFns.push(fn);
    });
  });

  afterEach(() => {
    jest.resetAllMocks();
    cleanupFns = [];
  });

  it('returns default message when no address is present', () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    expect(enderecoPadronizado.value).toBe('Aguardando localização...');
  });

  it('formats address when all fields are present', async () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    AddressCache.getInstance().setCurrentAddress({
      logradouro: 'Rua das Flores',
      numero: '123',
      bairro: 'Centro',
      municipio: 'São Paulo',
      siglaUF: 'SP',
      cep: '01000-000',
    });
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Rua das Flores, 123, Centro, São Paulo, SP, 01000-000');
  });

  it('formats address omitting empty fields', async () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    AddressCache.getInstance().setCurrentAddress({
      logradouro: 'Av. Brasil',
      numero: '',
      bairro: null,
      municipio: 'Rio de Janeiro',
      siglaUF: 'RJ',
      cep: '',
    });
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Av. Brasil, Rio de Janeiro, RJ');
  });

  it('updates when address changes', async () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    AddressCache.getInstance().setCurrentAddress({
      logradouro: 'Rua A',
      numero: '1',
      bairro: 'Bairro A',
      municipio: 'Cidade A',
      siglaUF: 'AA',
      cep: '11111-111',
    });
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Rua A, 1, Bairro A, Cidade A, AA, 11111-111');

    AddressCache.getInstance().setCurrentAddress({
      logradouro: 'Rua B',
      numero: '2',
      bairro: 'Bairro B',
      municipio: 'Cidade B',
      siglaUF: 'BB',
      cep: '22222-222',
    });
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Rua B, 2, Bairro B, Cidade B, BB, 22222-222');
  });

  it('does not update if address is null or undefined', async () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    AddressCache.getInstance().setCurrentAddress(null);
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Aguardando localização...');
    AddressCache.getInstance().setCurrentAddress(undefined);
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Aguardando localização...');
  });

  it('unsubscribes observer on unmount', () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    const instance = AddressCache.getInstance();
    const unsubscribeSpy = jest.spyOn(instance, 'unsubscribe');
    // Simulate component unmount
    cleanupFns.forEach(fn => fn());
    expect(unsubscribeSpy).toHaveBeenCalled();
    // Should not throw if called again
    expect(() => cleanupFns.forEach(fn => fn())).not.toThrow();
  });

  it('handles missing municipio or siglaUF gracefully', async () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    AddressCache.getInstance().setCurrentAddress({
      logradouro: 'Rua X',
      numero: '10',
      bairro: 'Bairro X',
      municipio: '',
      siglaUF: '',
      cep: '99999-999',
    });
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Rua X, 10, Bairro X, 99999-999');
  });

  it('handles only municipio or only siglaUF present', async () => {
    const { enderecoPadronizado } = useAddressDisplayer();
    AddressCache.getInstance().setCurrentAddress({
      logradouro: 'Rua Y',
      numero: '20',
      bairro: 'Bairro Y',
      municipio: 'Cidade Y',
      siglaUF: '',
      cep: '',
    });
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Rua Y, 20, Bairro Y, Cidade Y');

    AddressCache.getInstance().setCurrentAddress({
      logradouro: 'Rua Z',
      numero: '30',
      bairro: 'Bairro Z',
      municipio: '',
      siglaUF: 'ZZ',
      cep: '',
    });
    await nextTick();
    expect(enderecoPadronizado.value).toBe('Rua Z, 30, Bairro Z, ZZ');
  });
